<script>
 import {passwordsWindow,passwordsCapabilities,passwordsRows,passwordsAuthorized,passwordsMenus} from './passwords-assistant.js';
 import {createIdentityView} from './identity-assistant-core.js';
 import './identity-assistants.css';
 let {state: passwordsState,profile,window:actualWindow=null,windowId=actualWindow?.id,keychain=null,preferences=null,sceneSession=null,execute,registerView=()=>()=>{},available=true,active=true,controls={},showMenuBar=false}=$props();
 let root=$state(null),error=$state(''),passcode=$state(''),chainPassword=$state(''),name=$state(''),account=$state(''),service=$state(''),secret=$state(''),comment=$state(''),type=$state('password'),show=$state(false),groupName=$state(''),members=$state([]),editingGroupId=$state(null),challenge=$state('local invented challenge');
 const session=$derived(passwordsWindow(passwordsState,windowId)),cap=$derived(passwordsCapabilities(profile)),chain=$derived(keychain?.keychains.find(k=>k.id===session?.keychainId)),authorized=$derived(!!session&&!!keychain&&!!preferences&&!!sceneSession&&passwordsAuthorized(session,chain,preferences,sceneSession)),rows=$derived(authorized?passwordsRows(keychain,session):[]),selected=$derived(authorized?keychain.items.find(i=>i.id===session.selectedId&&i.kind==='password'&&i.keychainId===session.keychainId):null),menus=$derived(passwordsMenus({authorized,selected,session}));
 async function run(suffix,payload={}){if(!root?.isConnected||!available||!active)return;const mounted=root,original=session;const result=await execute('passwords.'+suffix,{windowId},payload);if(root===mounted&&session===original)error=result?.status==='rejected'?result.error?.message??'Operation unavailable.':'';return result;}
 async function menu(item){if(!item.enabled)return;await run('menu',{menu:null});await run(item.request.command.slice(10),item.request.payload);}
 function openGroup(group=null){editingGroupId=group?.id??null;groupName=group?.name??'';members=[...(group?.memberUserIds??[])];return run('panel',{panel:'group'});}
 $effect(()=>{if(session?.panel!=='group'){editingGroupId=null;groupName='';members=[];}});
 $effect(()=>{if(!root||!session)return;const original=session,view=createIdentityView({root,getRoot:()=>root,getSession:()=>passwordsWindow(passwordsState,windowId),available:()=>available&&active});const remove=registerView(windowId,view);return ()=>{view.dispose();if(typeof remove==='function')remove();else registerView(windowId,null,view);};});
 $effect(()=>{const panel=session?.panel,id=selected?.id;show=false;passcode='';chainPassword='';if(panel==='edit'&&selected&&authorized){name=selected.name;account=selected.account;service=selected.service;secret=selected.passwordDetails.type==='passkey'?'':selected.secret;comment=selected.comment;type=selected.passwordDetails.type;}else if(panel==='new'){name='';account='';service='';secret='';comment='';type='password';}});
 $effect(()=>{if(!authorized){secret='';show=false;}});
 const categories=[['all','All','▦'],['passkey','Passkeys','⚿'],['password','Passwords','●'],['wifi','Wi-Fi','◉'],['security','Security','⚠'],['deleted','Deleted','▥']];
</script>
{#if session}<section bind:this={root} class="identity-native passwords-native" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} aria-label={cap.label}>
 {#if cap.windows||showMenuBar}<nav class="identity-menubar" aria-label="Application menus">{#each menus as m}<button data-identity-control={'menu-'+m.id} class:chosen={session.menu===m.id} onclick={()=>run('menu',{menu:session.menu===m.id?null:m.id})}>{m.label}</button>{/each}</nav>{/if}
 {#if session.menu}<div class="identity-menu" role="menu">{#each menus.find(m=>m.id===session.menu)?.children??[] as item}<button role="menuitem" disabled={!item.enabled} onclick={()=>menu(item)}>{item.label}</button>{/each}</div>{/if}
 <header class="identity-toolbar"><strong>{cap.label}</strong><button data-identity-control="lock" onclick={()=>run(authorized?'lock':'panel',authorized?{}:{panel:'authenticate'})}>{authorized?'Lock':'Unlock'}</button><button data-identity-control="new" disabled={!authorized} onclick={()=>run('panel',{panel:'new'})}>＋</button><span></span><input data-identity-control="search" type="search" aria-label="Search credentials" placeholder="Search" value={session.search} disabled={!authorized} oninput={e=>run('navigate',{search:e.currentTarget.value})}/></header>
 <div class="passwords-layout"><aside><select aria-label="Original keychain" data-identity-control="keychain" value={session.keychainId} onchange={e=>run('navigate',{keychainId:e.currentTarget.value})}>{#each keychain?.keychains??[] as k}<option value={k.id}>{k.name}{k.locked?' · Locked':''}</option>{/each}</select><div class="category-grid">{#each categories as cat}<button data-identity-control={'category-'+cat[0]} class:chosen={session.category===cat[0]} onclick={()=>run('navigate',{category:cat[0],selectedId:null})}><b>{cat[2]}</b><span>{cat[1]}</span><small>{authorized?passwordsRows(keychain,{...session,category:cat[0],search:''}).length:'—'}</small></button>{/each}</div><h3>Shared Groups · Local</h3>{#if authorized}{#each keychain.sharedGroups as g}<div class="group-row"><button data-identity-control={'group-'+g.id} class:chosen={session.category==='group'&&session.groupId===g.id} onclick={()=>run('navigate',{category:'group',groupId:g.id,selectedId:null})}>{g.name}</button><button data-identity-control={'edit-group-'+g.id} aria-label={'Edit '+g.name} onclick={()=>openGroup(g)}>…</button><button aria-label={'Delete '+g.name} onclick={()=>run('group',{operation:'delete',groupId:g.id})}>−</button></div>{/each}{/if}<button data-identity-control="new-group" disabled={!authorized} onclick={()=>openGroup()}>＋ New Group</button></aside>
 <div class="credential-list" aria-label="Original credential list">{#if authorized}{#each rows as row}<button data-identity-control={'item-'+row.id} class:chosen={row===selected} onclick={()=>run('navigate',{selectedId:row.id})}><span class="credential-mark">{row.name.slice(0,1).toUpperCase()}</span><span><b>{row.name}</b><small>{row.account||row.service||row.passwordDetails.type}</small></span></button>{/each}{#if !rows.length}<p class="identity-empty">No invented credentials in this category.</p>{/if}{:else}<p class="identity-empty">Unlock to view credentials.</p>{/if}</div>
 <main class="credential-detail">{#if !authorized}<div class="identity-empty"><div class="lock-emblem">⚿</div><h2>Passwords Are Locked</h2><p>Authenticate the current fictional scene user and the original “{chain?.name??'login'}” keychain.</p><button data-identity-control="authenticate" onclick={()=>run('panel',{panel:'authenticate'})}>Unlock Passwords</button></div>{:else if selected}<h2>{selected.name}</h2><dl><dt>User Name</dt><dd>{selected.account||'—'} <button data-identity-control="copy-account" onclick={()=>run('copy',{field:'account'})}>Copy</button></dd><dt>{selected.passwordDetails.type==='wifi'?'Network':selected.passwordDetails.type==='passkey'?'Relying Party':'Website'}</dt><dd>{selected.service||'—'}</dd>{#if selected.passwordDetails.type!=='passkey'}<dt>Password</dt><dd><button data-identity-control="reveal" disabled={selected.passwordDetails.deletedAt!==null} onclick={()=>show=!show}>{show?selected.secret:'••••••••••••'}</button><button data-identity-control="copy-password" disabled={selected.passwordDetails.deletedAt!==null} onclick={()=>run('copy',{field:'secret'})}>Copy</button></dd>{:else}<dt>Local Passkey</dt><dd>P-256 · {selected.passwordDetails.passkey.signCount} verified assertions</dd><dt>Credential ID</dt><dd class="break-word">{selected.passwordDetails.passkey.credentialId}</dd>{/if}<dt>Modified</dt><dd>{new Date(selected.modifiedAt).toISOString()}</dd><dt>Notes</dt><dd>{selected.comment||'—'}</dd><dt>Group</dt><dd><select data-identity-control="assign-group" value={selected.passwordDetails.groupId??''} onchange={e=>run('group',{operation:'assign',groupId:e.currentTarget.value||null,itemId:selected.id})}><option value="">Not Shared</option>{#each keychain.sharedGroups as g}<option value={g.id}>{g.name}</option>{/each}</select></dd></dl>
 {#if selected.passwordDetails.deletedAt!==null}<p>Deleted locally. Restore or permanently erase this original entry. No remote vault is involved.</p><button data-identity-control="restore" onclick={()=>run('item',{operation:'restore',itemId:selected.id})}>Recover</button><button data-identity-control="erase" onclick={()=>run('item',{operation:'erase',itemId:selected.id})}>Delete Permanently</button>{:else}<div class="identity-actions"><button data-identity-control="edit" onclick={()=>run('panel',{panel:'edit'})}>Edit</button><button data-identity-control="delete" onclick={()=>run('item',{operation:'delete',itemId:selected.id})}>Delete Password</button></div>{#if selected.passwordDetails.type==='passkey'}<label>Local challenge<input data-identity-control="challenge" bind:value={challenge} maxlength="1024"/></label><button data-identity-control="sign" onclick={()=>run('sign',{challenge})}>Sign and Verify Locally</button>{#if session.signature}<output class="signature">{session.signature}</output><p>Verified for “{session.challenge}”. This is not website sign-in.</p>{/if}{/if}{/if}
 {:else}<div class="identity-empty"><h2>{session.category==='security'?'Local Security Checks':'Select a Password'}</h2><p>{session.category==='security'?'Lists short (under 12 characters) or reused invented secrets. No breach database or host telemetry is consulted.':'Create an invented password, Wi-Fi credential, or cryptographic local passkey.'}</p></div>{/if}</main></div>
 <footer><span role="status">{error||session.status}</span><details><summary>Local scope</summary><p>{cap.disclosure}</p><p>Default fictional scene passcode: scene. Original login keychain: trail-demo; System: system-demo. Deleted entries are retained until erased locally rather than claiming an iCloud 30-day purge.</p></details></footer>
 {#if session.panel!=='none'}<div class="identity-backdrop"><section class="identity-sheet" role="dialog" aria-modal="true" aria-label={session.panel}><header><h2>{session.panel==='authenticate'?'Unlock Passwords':session.panel==='new'?'New Invented Credential':session.panel==='edit'?'Edit Credential':session.panel==='group'?'New Shared Group':'About Local Passwords'}</h2><button data-identity-control="sheet-close" onclick={()=>run('panel',{panel:'none'})}>×</button></header>
 {#if session.panel==='authenticate'}<p>Never enter real passwords. Both challenges refer to the original local scene graphs.</p><label>Scene passcode<input data-identity-control="scene-passcode" type="password" bind:value={passcode} maxlength="128"/></label><label>Keychain password<input data-identity-control="chain-passcode" type="password" bind:value={chainPassword} maxlength="256"/></label><button data-identity-control="unlock-confirm" onclick={async()=>{await run('authenticate',{passcode,keychainPassword:chainPassword});passcode='';chainPassword='';}}>Unlock</button>
 {:else if (session.panel==='new'||session.panel==='edit')&&authorized}<label>Type<select data-identity-control="credential-type" bind:value={type} disabled={session.panel==='edit'}><option value="password">Password</option><option value="wifi">Wi-Fi · local credential</option><option value="passkey">Passkey · cryptographic local credential</option></select></label><label>Title<input data-identity-control="credential-name" bind:value={name} maxlength="256"/></label><label>User Name<input data-identity-control="credential-account" bind:value={account} maxlength="256"/></label><label>{type==='passkey'?'Relying Party (invented .invalid domain)':type==='wifi'?'Network Name':'Website'}<input data-identity-control="credential-service" bind:value={service} maxlength="256"/></label>{#if type!=='passkey'}<label>Invented Password<input data-identity-control="credential-secret" type="password" bind:value={secret} maxlength="16384"/></label>{:else}<p>Generates real P-256 key material using Web Crypto. The private JWK is retained only in the original Keychain item secret, plaintext local scene data.</p>{/if}<label>Notes<textarea data-identity-control="credential-comment" bind:value={comment} maxlength="4096"></textarea></label><button data-identity-control="save" onclick={async()=>{const p={operation:session.panel==='new'?'create':'update',name,account,service,comment};if(session.panel==='new')p.type=type;else p.itemId=selected.id;if(type!=='passkey')p.secret=secret;await run('item',p);secret='';}}>Save</button>
 {:else if session.panel==='group'&&authorized}<label>Group Name<input data-identity-control="group-name" bind:value={groupName} maxlength="128"/></label><fieldset><legend>Actual fictional scene users</legend>{#each sceneSession.users as u}<label class="identity-check"><input type="checkbox" checked={members.includes(u.id)} onchange={e=>members=e.currentTarget.checked?[...members,u.id]:members.filter(id=>id!==u.id)}/>{u.name} ({u.id})</label>{/each}</fieldset><button data-identity-control="group-save" onclick={()=>run('group',{operation:editingGroupId?'update':'create',...(editingGroupId?{groupId:editingGroupId}:{}),name:groupName,memberUserIds:members})}>{editingGroupId?'Save Original Group':'Create Local Group'}</button>{:else}<p>{cap.disclosure}</p>{/if}{#if error}<p class="identity-error" role="alert">{error}</p>{/if}</section></div>{/if}
</section>{/if}
